// session.rs:836 — 会话初始化完成后立即启动
memories::start_memories_startup_task(
  &sess,
  Arc::clone(&config),
  &session_configuration.session_source,
);

// Feature::Sqlite + Feature::MemoryTool 必须启用
// config.memories:
//   max_raw_memories_for_consolidation: 50
//   max_age_days: 30
//   min_rollout_idle_hours: 1

// state/src/runtime/memories.rs
// claim_stage1_jobs_for_startup() 扫描条件：
//   AND threads.memory_mode = 'enabled'
//   AND threads.id != current_thread_id
//   AND threads.updated_at_ms >= max_age_cutoff   (30天内)
//   AND threads.updated_at_ms <= idle_cutoff       (闲置 ≥ 1h)
//   AND stage1_outputs.source_updated_at < threads.updated_at
//
// 找到 3 个符合条件的历史线程：
//   thread-A (updated: 2h ago, branch: main)
//   thread-B (updated: 5h ago, branch: feat/auth)
//   thread-C (updated: 1d ago, branch: fix/login)

// JOB_KIND_MEMORY_STAGE1 = "memory_stage1"
// DEFAULT_RETRY_REMAINING = 3
//
// worker A (当前会话) 尝试争抢 thread-A：
INSERT INTO jobs (
  kind='memory_stage1', job_key=thread_id,
  status='running', ownership_token='tok-abc',
  lease_until=now+3600, retry_remaining=3,
  input_watermark=source_updated_at
)
ON CONFLICT DO UPDATE SET ...
WHERE
  (jobs.status != 'running' OR jobs.lease_until <= now)
  AND retry_remaining > 0
  AND running_job_count < max_running_jobs

// 结果:
// thread-A → Claimed { ownership_token: "tok-abc" } ✓
// thread-B → SkippedRunning (另一 worker 持有 lease) ✗
// thread-C → SkippedUpToDate (stage1_outputs 已是最新) ✗

// 对 thread-A 执行 Stage1 提取
// 读取 thread-A 的 rollout 文件，调用模型提取记忆

// 提取结果：
raw_memory = """
- 在 main 分支重构了认证模块
- 修复了 OAuth 回调路径 bug
- 使用 argon2 替换了 bcrypt
"""

rollout_summary = """
完成了认证模块重构。主要改动：
1. src/auth.rs：拆分为 oauth.rs + local.rs
2. 修复 callback 路径缺失 state 参数的 bug
3. 密码哈希从 bcrypt 迁移到 argon2
"""

// 写入 SQLite + 触发 Phase2
mark_stage1_job_succeeded(
  thread_id, &"tok-abc", source_updated_at,
  raw_memory, rollout_summary, Some("rollout-thread-a"),
).await?;
// → 内部自动 enqueue_global_consolidation(input_watermark)

// JOB_KIND_MEMORY_CONSOLIDATE_GLOBAL = "memory_consolidate_global"
// MEMORY_CONSOLIDATION_JOB_KEY = "global" (全局单例)
//
// try_claim_global_phase2_job() 检查条件：
//   input_watermark(1735000000) > last_success_watermark(1734000000)
//   retry_remaining > 0
//   NOT (status='running' AND lease_until > now)
//
// Phase2 Prompt 格式（来自 core/tests/suite/memories.rs）：
// "Current selected Phase 1 inputs:"
// "- selected inputs this run: 1"
// "- newly added since the last successful Phase 2 run: 1"
// "- removed from the last successful Phase 2 run: 0"
// "- [added] thread_id=thread-A, git_branch=main, cwd=/workspace/auth"
// "Removed from the last successful Phase 2 selection:"
// "- none"

// web_search 完成后，当前线程被标记为 polluted
// config.memories.no_memories_if_mcp_or_web_search = true

mark_thread_memory_mode_polluted(
  current_thread_id
).await?;
// → UPDATE threads SET memory_mode = 'polluted'
//   WHERE id = ? AND memory_mode != 'polluted'
//
// 若该线程曾入选 Phase2 baseline（selected_for_phase2=1）：
// → 自动 enqueue_global_consolidation(source_updated_at)
//   下次 Phase2 运行时：
//   phase2_prompt 会显示：
//   "- removed from the last successful Phase 2 run: 1"
//   "- thread_id=current_thread_id, ..."
//   polluted 线程从 selected_outputs 移入 removed
